// Details page of a theme (/themes/?id=...) and of a sub style (/themes/?id=...&style=...),
// data comes from /data/details/<id>.json (generated by the workflow).
// Layout inspired by the SteamTheme store page (media viewer + sidebar) and library (play bar).

const RELEASES_PER_PAGE = 10;

// Badges, pills and logos in the readmes are not theme screenshots
const IGNORED_IMAGES = /shields\.io|badge|\/pills?\/|logo|favicon|avatar|\.svg($|\?)/i;
const GENERIC_ALT = /^(preview|image|img|screenshot|banner|placeholder)?$/i;

const esc = value => ST.escapeHtml(value ?? '');




/* Small building blocks */

function hostOf(url) {
    try {
        return new URL(url).host;
    } catch {
        return url;
    }
}

function initialsOf(name) {
    return name.split(/\s+/).map(word => word[0]).join('').slice(0, 3);
}

function infoRow(iconName, label, valueHtml) {
    return valueHtml || valueHtml === 0
        ? `<div class="info-row"><dt>${ST.icon(iconName)}${label}</dt><dd>${valueHtml}</dd></div>`
        : '';
}

function playStat(iconName, label, value) {
    return value || value === 0 ? `
        <div class="play-stat">
            ${ST.icon(iconName)}
            <div>
                <p class="play-stat-label">${label}</p>
                <p class="play-stat-value">${esc(value)}</p>
            </div>
        </div>` : '';
}

function bigStats(items) {
    return `
        <div class="panel big-stats">
            ${items.map(([value, label]) => `<div class="big-stat"><b>${esc(value)}</b><span>${label}</span></div>`).join('')}
        </div>`;
}

function linkButton(iconName, label, href, className = '') {
    return `<a class="link-button ${className}" href="${esc(href)}">${ST.icon(iconName)}<span>${label}</span></a>`;
}

function iconLink(iconName, label, href) {
    return `<a class="icon-link" href="${esc(href)}" title="${esc(label)}" aria-label="${esc(label)}">${ST.icon(iconName)}</a>`;
}

const KOFI_LINK = () => linkButton('heart', 'Support on Ko-fi', 'https://kofi.spacetheme.net', 'kofi');

function otherList(items) {
    return items.map(item => `
        <a class="other-theme" href="${esc(item.href)}">
            ${item.image
                ? `<img src="${esc(item.image)}" alt="" loading="lazy" data-fallback${item.fallback ? ` data-fallback-src="${esc(item.fallback)}"` : ''}>`
                : `<span class="other-initials">${esc(initialsOf(item.title))}</span>`}
            <div>
                <p>${esc(item.title)}</p>
                <span>${esc(item.subtitle)}</span>
            </div>
        </a>`).join('');
}

function flashButton(button, iconName) {
    const original = button.innerHTML;
    button.innerHTML = ST.icon(iconName);
    button.disabled = true;
    setTimeout(() => {
        button.innerHTML = original;
        button.disabled = false;
    }, 1500);
}

// raw.githubusercontent.com allows CORS, so files can be saved/copied directly
function bindFileActions(container) {
    container?.addEventListener('click', async e => {
        const button = e.target.closest('[data-action]');
        if (!button) return;
        const { action, url, name } = button.dataset;
        try {
            const res = await fetch(url);
            if (!res.ok) throw new Error(res.status);
            if (action === 'copy') {
                await navigator.clipboard.writeText(await res.text());
                flashButton(button, 'check');
            } else {
                const link = document.createElement('a');
                link.href = URL.createObjectURL(await res.blob());
                link.download = name;
                link.click();
                URL.revokeObjectURL(link.href);
            }
        } catch {
            window.open(url, '_blank');
        }
    });
}

function fileButtons(file, label = 'Download') {
    return `
        <button class="btn blue" data-action="download" data-url="${esc(file.url)}" data-name="${esc(file.name.split('/').pop())}">
            ${ST.icon('download')}<span>${label}</span>
        </button>
        <button class="btn icon-button" data-action="copy" data-url="${esc(file.url)}" title="Copy CSS" aria-label="Copy CSS">${ST.icon('copy')}</button>`;
}




/* Gallery */

function imageKey(img) {
    return img.dataset.canonicalSrc || img.getAttribute('src');
}

// Alt text, otherwise the table header / title row above the image (e.g. "Library home")
function imageCaption(img) {
    const alt = (img.getAttribute('alt') || '').trim();
    if (!GENERIC_ALT.test(alt)) return alt;

    const cell = img.closest('td, th');
    if (cell) {
        const index = cell.cellIndex;
        const rows = [...cell.closest('table').rows];
        for (let i = rows.indexOf(cell.parentElement) - 1; i >= 0; i--) {
            const above = rows[i].cells[index];
            const text = above?.textContent.trim();
            if (above && text && !above.querySelector('img')) return text;
        }
    }
    const summary = img.closest('details')?.querySelector('summary')?.textContent.trim();
    return summary || alt || 'Preview';
}

function collectGallery(readme, items = []) {
    const seen = new Set(items.map(item => item.key));
    if (readme) {
        const doc = new DOMParser().parseFromString(readme, 'text/html');
        doc.querySelectorAll('img').forEach(img => {
            const key = imageKey(img);
            const size = parseInt(img.getAttribute('height') || img.getAttribute('width'));
            if (!key || seen.has(key) || IGNORED_IMAGES.test(key) || (size && size < 120)) return;
            seen.add(key);
            items.push({ key, src: img.getAttribute('src'), caption: imageCaption(img) });
        });
    }
    return items;
}

// Big image with a strip of thumbnails, like the screenshots on the store page
function renderMedia(items, placeholder) {
    if (!items.length) {
        return `<div class="panel media"><div class="media-main empty"><span class="initials">${esc(initialsOf(placeholder))}</span></div></div>`;
    }
    const strip = items.length > 1 ? `
        <div class="media-strip-wrap">
            <button class="strip-button" data-step="-1" aria-label="Previous image">${ST.icon('chevronLeft')}</button>
            <div class="media-strip">
                ${items.map((item, index) => `
                    <button class="thumb" data-index="${index}" aria-label="Show ${esc(item.caption)}">
                        <img src="${esc(item.src)}" alt="" loading="lazy">
                    </button>`).join('')}
            </div>
            <button class="strip-button" data-step="1" aria-label="Next image">${ST.icon('chevronRight')}</button>
        </div>` : '';
    return `
        <div class="panel media">
            <button class="media-main" aria-label="Open image in full size">
                <img alt="">
                <span class="caption"></span>
            </button>
            ${strip}
        </div>`;
}

function bindMedia(root, items) {
    const media = root.querySelector('.media');
    const main = media?.querySelector('.media-main:not(.empty)');
    if (!main) return;

    const img = main.querySelector('img');
    const caption = main.querySelector('.caption');
    const strip = media.querySelector('.media-strip');
    const thumbs = [...media.querySelectorAll('.thumb')];
    let current = 0;

    function select(index) {
        current = (index + items.length) % items.length;
        img.src = items[current].src;
        img.alt = items[current].caption;
        caption.textContent = items[current].caption;
        caption.hidden = !items[current].caption;
        thumbs.forEach((thumb, i) => thumb.classList.toggle('active', i === current));
        const thumb = thumbs[current];
        if (strip && thumb) {
            strip.scrollTo({ left: thumb.offsetLeft - (strip.clientWidth - thumb.offsetWidth) / 2, behavior: 'smooth' });
        }
    }

    main.addEventListener('click', () => openLightbox(items, current));
    media.addEventListener('click', e => {
        const thumb = e.target.closest('.thumb');
        const step = e.target.closest('[data-step]');
        if (thumb) select(Number(thumb.dataset.index));
        else if (step) select(current + Number(step.dataset.step));
    });
    select(0);
}

function openLightbox(items, index) {
    const previousFocus = document.activeElement;
    const box = document.createElement('div');
    box.className = 'lightbox';
    box.setAttribute('role', 'dialog');
    box.setAttribute('aria-modal', 'true');
    box.innerHTML = `
        <button class="lightbox-button close" aria-label="Close">${ST.icon('close')}</button>
        ${items.length > 1 ? `
            <button class="lightbox-button prev" aria-label="Previous image">${ST.icon('chevronLeft')}</button>
            <button class="lightbox-button next" aria-label="Next image">${ST.icon('chevronRight')}</button>` : ''}
        <img alt="">
        <p class="lightbox-caption"></p>`;

    const img = box.querySelector('img');
    const caption = box.querySelector('.lightbox-caption');

    function show(i) {
        index = (i + items.length) % items.length;
        img.src = items[index].src;
        img.alt = items[index].caption;
        caption.innerHTML = `${esc(items[index].caption)}<span>${index + 1} / ${items.length}</span>`;
    }
    function close() {
        box.remove();
        document.removeEventListener('keydown', onKey);
        previousFocus?.focus();
    }
    function onKey(e) {
        if (e.key === 'Escape') close();
        else if (e.key === 'ArrowLeft') show(index - 1);
        else if (e.key === 'ArrowRight') show(index + 1);
    }

    box.addEventListener('click', e => {
        if (e.target === box) close();
        else if (e.target.closest('.close')) close();
        else if (e.target.closest('.prev')) show(index - 1);
        else if (e.target.closest('.next')) show(index + 1);
    });
    document.addEventListener('keydown', onKey);

    show(index);
    document.body.append(box);
    box.querySelector('.close').focus();
}




/* Tabs */

// Same html as on github.com, screenshots open in the lightbox instead of a new tab
function renderReadmeTab(panel, readme, gallery) {
    panel.innerHTML = `<div class="markdown readme">${readme}</div>`;
    const indexByKey = new Map(gallery.map((item, index) => [item.key, index]));

    panel.querySelectorAll('img').forEach(img => {
        if (!indexByKey.has(imageKey(img))) return;
        const link = img.closest('a');
        // Only take over links that just point to the image itself
        if (link && !/raw\.githubusercontent|camo\.githubusercontent|user-images|\/assets\//.test(link.href)) return;
        (link || img).classList.add('gallery-link');
        (link || img).addEventListener('click', e => {
            e.preventDefault();
            openLightbox(gallery, indexByKey.get(imageKey(img)));
        });
    });
}

function renderRelease(release, index) {
    const badges = [
        index === 0 && !release.prerelease ? '<span class="badge accent">Latest</span>' : '',
        release.prerelease ? '<span class="badge status-wip">Pre-release</span>' : ''
    ].join('');
    const name = release.name && release.name !== release.tag ? `<span class="version-name">${esc(release.name)}</span>` : '';

    return `
        <div class="version" data-index="${index}">
            <div class="version-header">
                <div class="version-title">
                    <h3>${esc(release.tag)}</h3>
                    ${name}${badges}
                </div>
                <span class="version-meta">${ST.formatDate(release.date)} · ${ST.formatNumber(release.downloads)} downloads</span>
                <button class="btn small version-toggle" aria-expanded="false">Show More</button>
            </div>
            <div class="version-body" hidden></div>
        </div>`;
}

// Release notes can be huge, so they are only rendered when opened
function renderReleaseBody(release) {
    const assets = release.assets.map(asset => `
        <a class="asset" href="${esc(asset.url)}">
            ${ST.icon('download')}
            <span class="asset-name">${esc(asset.name)}</span>
            <span class="asset-meta">${ST.formatSize(asset.size)} · ${ST.formatNumber(asset.downloads)} downloads</span>
        </a>`).join('');

    return `
        <div class="markdown">${release.body || '<p class="empty">No release notes.</p>'}</div>
        ${assets ? `<div class="assets">${assets}</div>` : ''}
        <a class="external-link" href="${esc(release.url)}">${ST.icon('external')}View on GitHub</a>`;
}

function renderVersionsTab(panel, releases, commitMode) {
    let shown = 0;
    panel.innerHTML = `
        ${commitMode ? '<p class="notice">This theme is now updated through commits, the releases below are older versions.</p>' : ''}
        <div class="panel">
            <h3 class="panel-title">Versions <span class="count">${releases.length}</span></h3>
            <div class="version-list"></div>
            <button class="btn small load-more" hidden>Show older versions</button>
        </div>`;

    const list = panel.querySelector('.version-list');
    const loadMore = panel.querySelector('.load-more');

    function showMore() {
        const next = releases.slice(shown, shown + RELEASES_PER_PAGE);
        list.insertAdjacentHTML('beforeend', next.map((release, i) => renderRelease(release, shown + i)).join(''));
        shown += next.length;
        loadMore.hidden = shown >= releases.length;
    }

    function toggle(version, open) {
        const body = version.querySelector('.version-body');
        const button = version.querySelector('.version-toggle');
        if (open && !body.innerHTML) body.innerHTML = renderReleaseBody(releases[version.dataset.index]);
        body.hidden = !open;
        version.classList.toggle('open', open);
        button.textContent = open ? 'Show Less' : 'Show More';
        button.setAttribute('aria-expanded', open);
    }

    list.addEventListener('click', e => {
        const header = e.target.closest('.version-header');
        if (!header || e.target.closest('a')) return;
        const version = header.parentElement;
        toggle(version, !version.classList.contains('open'));
    });
    loadMore.addEventListener('click', showMore);

    showMore();
    if (!commitMode) toggle(list.firstElementChild, true);
}

// One panel per day, like the settings sections of the SteamTheme
function renderCommitsTab(panel, commits, notice, historyUrl) {
    const groups = new Map();
    for (const commit of commits) {
        const day = ST.formatDate(commit.date);
        if (!groups.has(day)) groups.set(day, []);
        groups.get(day).push(commit);
    }

    panel.innerHTML = `
        ${notice ? `<p class="notice">${notice}</p>` : ''}
        <div class="commit-groups">
            ${[...groups].map(([day, list]) => `
                <div class="panel">
                    <h3 class="panel-title">${ST.icon('commit')}Commits on ${day}</h3>
                    ${list.map(commit => `
                        <a class="commit" href="${esc(commit.url)}">
                            ${commit.avatar ? `<img class="avatar" src="${esc(commit.avatar)}&s=64" alt="" loading="lazy">` : '<span class="avatar"></span>'}
                            <div class="commit-info">
                                <p class="commit-title">${esc(commit.title)}</p>
                                <p class="commit-meta"><b>${esc(commit.author)}</b> committed ${ST.timeAgo(commit.date)}</p>
                            </div>
                            <code class="sha">${esc(commit.sha)}</code>
                        </a>`).join('')}
                </div>`).join('')}
        </div>
        ${historyUrl ? `<a class="external-link" href="${esc(historyUrl)}">${ST.icon('external')}Full commit history</a>` : ''}`;
}

// Roadmap from ROADMAP.md: one panel per heading, sub tasks indented below their task
function inlineMarkdown(text) {
    return esc(text)
        .replace(/`([^`]+)`/g, '<code>$1</code>')
        .replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>')
        .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2">$1</a>');
}

function countTasks(tasks) {
    return tasks.reduce((count, task) => {
        const sub = countTasks(task.tasks);
        return { done: count.done + (task.done ? 1 : 0) + sub.done, total: count.total + 1 + sub.total };
    }, { done: 0, total: 0 });
}

function renderTasks(tasks) {
    return tasks.map(task => `
        <div class="task${task.done ? ' done' : ''}">
            <div class="task-row">
                <span class="task-check" aria-label="${task.done ? 'Done' : 'Open'}">${task.done ? ST.icon('check') : ''}</span>
                <span class="task-text">${inlineMarkdown(task.text)}</span>
            </div>
            ${task.tasks.length ? `<div class="task-children">${renderTasks(task.tasks)}</div>` : ''}
        </div>`).join('');
}

function roadmapProgress({ done, total }) {
    const percent = total ? Math.round((done / total) * 100) : 0;
    return `
        <div class="roadmap-progress">
            <div class="progress-bar"><span style="width: ${percent}%"></span></div>
            <span>${done} / ${total} done · ${percent}%</span>
        </div>`;
}

function renderRoadmapTab(panel, roadmap) {
    panel.innerHTML = `
        <div class="roadmap">
            <div class="panel">
                <h3 class="panel-title">${ST.icon('flag')}Roadmap</h3>
                ${roadmapProgress(countTasks(roadmap.flatMap(section => section.tasks)))}
            </div>
            ${roadmap.map(section => {
                const count = countTasks(section.tasks);
                return `
                    <div class="panel">
                        <h3 class="panel-title">${esc(section.title || 'Tasks')} <span class="count">${count.done} / ${count.total}</span></h3>
                        ${renderTasks(section.tasks)}
                    </div>`;
            }).join('')}
        </div>`;
}

async function renderWebsitesTab(panel, theme, styles) {
    const cards = await Promise.all(styles.map(style => {
        const host = style.url && hostOf(style.url);
        return ST.render('themesCard', {
            href: `/themes/?id=${encodeURIComponent(theme.id)}&style=${encodeURIComponent(style.id)}`,
            name: style.name,
            description: `SpaceTheme for ${host || style.name}.`,
            preview: style.image
                ? ST.previewImage(style.image, `${style.name} preview`)
                : `<span class="initials">${esc(initialsOf(style.name))}</span>`,
            tags: host ? `<span class="tag">${esc(host)}</span>` : '',
            iconArrow: ST.icon('chevronRight'),
            meta: [
                ST.metaItem('commit', 'Last commit', style.commits[0]?.sha || '–'),
                ST.metaItem('clock', 'Last update', style.updated ? ST.timeAgo(style.updated) : '–'),
                ST.metaItem('image', 'Images', `${style.images.length} ${style.images.length === 1 ? 'image' : 'images'}`)
            ].join('')
        });
    }));
    if (panel.dataset.tab !== 'websites') return;
    panel.innerHTML = `<div class="theme-grid">${cards.join('')}</div>`;
    ST.applyImageFallbacks(panel);
}

function renderFilesTab(panel, files) {
    panel.innerHTML = `
        <div class="panel">
            <h3 class="panel-title">Files <span class="count">${files.length}</span></h3>
            ${files.map(file => `
                <div class="file-row">
                    ${ST.icon('file')}
                    <div class="file-info">
                        <p>${esc(file.name)}</p>
                        <span>${ST.formatSize(file.size)}</span>
                    </div>
                    ${fileButtons(file)}
                    <a class="btn icon-button" href="${esc(file.html)}" title="View source" aria-label="View source">${ST.icon('github')}</a>
                </div>`).join('')}
        </div>`;
    bindFileActions(panel.firstElementChild);
}




/* Page */

async function loadDetails(id) {
    return ST.fetchJson(`/data/details/${encodeURIComponent(id)}.json`)
        .catch(() => ({ readme: null, releases: [], commits: [] }));
}

// Renders the shared layout (components/details.html) and wires media, tabs and buttons
async function renderPage(root, page) {
    root.innerHTML = `<div class="page">${await ST.render('details', {
        ...page,
        iconBack: ST.icon('back'),
        tabs: page.tabs.map(tab => `
            <button class="tab" role="tab" data-tab="${tab.id}">
                ${ST.icon(tab.icon)}<span>${tab.label}</span>${tab.count ? `<span class="count">${tab.count}</span>` : ''}
            </button>`).join(''),
        hideMore: page.more ? '' : 'hidden'
    })}</div>`;

    document.title = `${page.documentTitle} - SpaceTheme`;
    document.querySelector('meta[name="description"]')?.setAttribute('content', page.description || '');

    bindMedia(root, page.gallery);
    bindFileActions(root.querySelector('.playbar'));

    const panel = root.querySelector('#tab-panel');
    const tabButtons = [...root.querySelectorAll('.tab[data-tab]')];
    root.querySelector('.details-content .tabs').hidden = !page.tabs.length;

    function openTab(id) {
        panel.dataset.tab = id || '';
        tabButtons.forEach(button => {
            button.classList.toggle('active', button.dataset.tab === id);
            button.setAttribute('aria-selected', button.dataset.tab === id);
        });
        if (page.renderers[id]) page.renderers[id](panel);
        else panel.innerHTML = '<p class="notice">There is no information about this theme yet.</p>';
    }

    function selectTab(id) {
        history.replaceState(null, '', `${location.search}#${id}`);
        openTab(id);
    }
    tabButtons.forEach(button => button.addEventListener('click', () => selectTab(button.dataset.tab)));

    // Buttons that open a tab instead of a download (e.g. "Websites" of the userstyles)
    root.querySelectorAll('[data-tab-link]').forEach(link => link.addEventListener('click', e => {
        e.preventDefault();
        selectTab(link.dataset.tabLink);
        root.querySelector('.details-content').scrollIntoView({ behavior: 'smooth', block: 'start' });
    }));

    const fromHash = page.tabs.find(tab => tab.id === location.hash.slice(1));
    openTab((fromHash || page.tabs[0])?.id);
}

// "Artworks | Plugin": switches between a theme and its extra repos ("projects" in themes.json)
function projectSwitch(owner, activeId) {
    if (!owner.projects?.length) return '';
    const base = `/themes/?id=${encodeURIComponent(owner.id)}`;
    const items = [
        { id: '', label: owner.projectLabel || owner.name, icon: owner.projectIcon || 'book', href: base },
        ...owner.projects.map(p => ({ id: p.id, label: p.label || p.name, icon: p.icon || 'book', href: `${base}&project=${encodeURIComponent(p.id)}` }))
    ];
    return `<nav class="tabs project-switch" aria-label="Projects">${items.map(item => `
        <a class="tab${item.id === activeId ? ' active' : ''}" href="${esc(item.href)}"${item.id === activeId ? ' aria-current="page"' : ''}>
            ${ST.icon(item.icon)}<span>${esc(item.label)}</span>
        </a>`).join('')}</nav>`;
}

// parent: the theme a project belongs to (/themes/?id=...&project=...), null for a normal theme
async function renderDetails(root, theme, themes, stats, parent = null) {
    const owner = parent || theme;
    const stat = stats.themes?.[theme.id] || {};
    const details = await loadDetails(theme.id);
    const styles = details.styles || [];
    const view = ST.themeView(theme, stat);
    const repoUrl = theme.repo;
    const commitMode = stat.changelog === 'commits' || !details.releases.length;
    const gallery = collectGallery(details.readme);

    const changelogTabs = [
        details.releases.length && { id: 'versions', label: 'Versions', icon: 'tag', count: details.releases.length },
        details.commits.length && { id: 'commits', label: 'Commits', icon: 'commit' }
    ];
    if (commitMode) changelogTabs.reverse();

    // Downloads are blue, links to other pages (Get, Websites) are green
    const label = theme.downloadLabel || 'Download';
    const primary = styles.length
        ? `<a class="btn green play-button" href="#websites" data-tab-link="websites">${ST.icon('globe')}<span>Websites</span></a>`
        : `<a class="btn ${/download/i.test(label) ? 'blue' : 'green'} play-button" href="${esc(view.download)}">${ST.icon('download')}<span>${esc(label)}</span></a>`;

    await renderPage(root, {
        documentTitle: theme.name,
        projectSwitch: projectSwitch(owner, theme.projectId || ''),
        backHref: '/themes/',
        backLabel: 'All Themes',
        titleLight: view.titleLight,
        titleBold: view.titleBold,
        badges: view.badges,
        description: view.description,   // GitHub repo description, themes.json as fallback
        tags: view.tags,
        headerActions: iconLink('github', 'View on GitHub', repoUrl),
        gallery,
        media: renderMedia(gallery.length ? gallery : [{ key: view.image, src: view.image, caption: '' }], theme.name),
        playbar: primary + [
            playStat('tag', 'Version', stat.version),
            playStat('clock', 'Last update', stat.updated && ST.timeAgo(stat.updated)),
            playStat('license', 'License', stat.license)
        ].join(''),
        aboutImage: `<img class="about-image" src="${esc(stat.socialImage || view.image)}" alt="" data-fallback${stat.image ? ` data-fallback-src="${esc(stat.image)}"` : ''}>`,
        infoRows: [
            infoRow('status', 'Status', esc(theme.status)),
            infoRow('tag', 'Releases', details.releases.length || ''),
            infoRow('github', 'Repository', stat.repo && `<a href="https://github.com/${esc(stat.repo)}">${esc(stat.repo)}</a>`),
            infoRow('issue', 'Open issues', stat.repo && ST.formatNumber(stat.issues)),
            infoRow('fork', 'Forks', stat.repo && ST.formatNumber(stat.forks))
        ].join(''),
        bigStats: stat.repo ? bigStats([[view.downloads, 'Downloads'], [view.stars, 'Stars']]) : '',
        links: [
            linkButton('issue', 'Report an issue', `${repoUrl}/issues/new/choose`),
            commitMode
                ? linkButton('commit', 'Commit history', `${repoUrl}/commits`)
                : linkButton('tag', 'All releases', `${repoUrl}/releases`),
            linkButton('globe', 'Join the community', 'https://discord.spacetheme.net'),
            KOFI_LINK()
        ].join(''),
        moreTitle: 'More Themes',
        more: otherList(themes
            .filter(t => t.id !== owner.id && !t.hidden)
            .map(t => {
                const other = ST.themeView(t, stats.themes?.[t.id]);
                const otherStat = stats.themes?.[t.id] || {};
                return { href: other.href, image: other.image, fallback: otherStat.image, title: t.name, subtitle: `${other.version} · ${other.downloads} downloads` };
            })),
        tabs: [
            details.readme && { id: 'readme', label: 'Readme', icon: 'book' },
            styles.length && { id: 'websites', label: 'Websites', icon: 'globe', count: styles.length },
            details.roadmap?.length && { id: 'roadmap', label: 'Roadmap', icon: 'flag' },
            ...changelogTabs
        ].filter(Boolean),
        renderers: {
            readme: panel => renderReadmeTab(panel, details.readme, gallery),
            roadmap: panel => renderRoadmapTab(panel, details.roadmap),
            websites: panel => renderWebsitesTab(panel, theme, styles),
            versions: panel => renderVersionsTab(panel, details.releases, theme.changelog === 'commits'),
            commits: panel => renderCommitsTab(
                panel, details.commits,
                details.releases.length ? '' : 'No versions released yet, here are the latest commits instead.',
                `${repoUrl}/commits`)
        }
    });
}

async function renderStylePage(root, theme, styleId, stats) {
    const stat = stats.themes?.[theme.id] || {};
    const details = await loadDetails(theme.id);
    const styles = details.styles || [];
    const style = styles.find(s => s.id === styleId);
    if (!style) return renderMessage(root, 'Website not found', `${theme.name} has no style for "${styleId}".`);

    const parentHref = `/themes/?id=${encodeURIComponent(theme.id)}`;
    const host = style.url && hostOf(style.url);
    const repoUrl = theme.repo;
    const title = ST.splitTitle(style.name);
    const gallery = collectGallery(style.readme, style.images.map(image => ({
        key: image.src,
        src: image.src,
        caption: image.name.replace(/\.[^.]+$/, '').replace(/[-_]+/g, ' ')
    })));

    const file = style.files.length === 1 ? style.files[0] : null;
    const primary = file
        ? `<div class="play-actions">${fileButtons(file).replace('class="btn blue"', 'class="btn blue play-button"')}</div>`
        : style.files.length
            ? `<a class="btn blue play-button" href="#files" data-tab-link="files">${ST.icon('download')}<span>Download</span></a>`
            : `<a class="btn green play-button" href="${esc(style.folder)}">${ST.icon('github')}<span>View folder</span></a>`;

    await renderPage(root, {
        documentTitle: `${style.name} - ${theme.name}`,
        backHref: `${parentHref}#websites`,
        backLabel: theme.name,
        ...title,
        badges: `<span class="badge accent">${esc(theme.name)}</span>`,
        // A folder has no description of its own, so it shows the one of the repo (GitHub)
        description: stat.description || theme.description || `SpaceTheme for ${host || style.name}, part of the ${theme.name}.`,
        tags: host ? `<span class="tag">${esc(host)}</span>` : '',
        headerActions: [
            style.url ? iconLink('globe', 'Open website', style.url) : '',
            iconLink('github', 'View folder on GitHub', style.folder)
        ].join(''),
        gallery,
        media: renderMedia(gallery, style.name),
        playbar: primary + [
            playStat('clock', 'Last update', style.updated && ST.timeAgo(style.updated)),
            playStat('commit', 'Last commit', style.commits[0]?.sha),
            playStat('globe', 'Website', host)
        ].join(''),
        aboutImage: `<img class="about-image" src="${esc(style.image || stat.image || stat.socialImage || ST.FALLBACK_IMAGE)}" alt="" data-fallback>`,
        infoRows: [
            infoRow('globe', 'Website', style.url && `<a href="${esc(style.url)}">${esc(host)}</a>`),
            infoRow('file', 'Files', style.files.length),
            infoRow('image', 'Images', style.images.length),
            infoRow('github', 'Folder', `<a href="${esc(style.folder)}">${esc(style.id)}</a>`)
        ].join(''),
        bigStats: bigStats([[style.commits.length, 'Commits'], [style.files.length, 'Files'], [style.images.length, 'Images']]),
        links: [
            style.url ? linkButton('globe', 'Open website', style.url) : '',
            linkButton('github', 'View folder on GitHub', style.folder),
            linkButton('issue', 'Report an issue', `${repoUrl}/issues/new/choose`),
            KOFI_LINK()
        ].join(''),
        moreTitle: 'More Websites',
        more: otherList(styles
            .filter(s => s.id !== style.id)
            .map(s => ({
                href: `${parentHref}&style=${encodeURIComponent(s.id)}`,
                image: s.image,
                title: s.name,
                subtitle: s.url ? hostOf(s.url) : s.id
            }))),
        tabs: [
            style.readme && { id: 'readme', label: 'Readme', icon: 'book' },
            style.files.length && { id: 'files', label: 'Files', icon: 'file', count: style.files.length },
            style.commits.length && { id: 'commits', label: 'Commits', icon: 'commit', count: style.commits.length }
        ].filter(Boolean),
        renderers: {
            readme: panel => renderReadmeTab(panel, style.readme, gallery),
            files: panel => renderFilesTab(panel, style.files),
            commits: panel => renderCommitsTab(panel, style.commits, '', style.folder.replace('/tree/', '/commits/'))
        }
    });
}
